import java.util.HashMap;import java.util.Map; public class Problem4_EmployeeIdLookup { static class Record{String id,dept;Record(String i,String d){id=i;dept=d;}} static Map<String,String>buildLookup(Record[]a){Map<String,String>m=new HashMap<>();for(Record r:a)m.put(r.id,r.dept);return m;} static String getDepartment(Map<String,String>m,String id){return m.getOrDefault(id,"Unknown");} public static void main(String[]x){Map<String,String>m=buildLookup(new Record[]{new Record("E390","Marketing")});System.out.println(getDepartment(m,"E390"));}}